3	     2	import java.util.HashMap;
4	     3	import java.util.List;
5	     4	import java.util.Map;
6	     5	
7	     6	/**
8	     7	 * The office doing business with one customer over the course of a scenario: it
9	     8	 * quotes premiums, writes the policies those quotes insure, and settles claims
10	     9	 * against the policies it has written.
11	    10	 *
12	    11	 * What the office carries from one operation to the next is its own
13	    12	 * bookkeeping, not the protocol's: how many contracts this customer already
14	    13	 * holds (so the next quote knows it is a follow-up) and which policy each quote
15	    14	 * wrote (so a later claim can be settled against it). A protocol revision
16	    15	 * renaming a field changes none of it; deciding that some quote does not count
17	    16	 * toward the customer's contracts would change it without touching a field
18	    17	 * name.
19	    18	 */
20	    19	public class ClaimOffice {
21	    20	
22	    21	    private final PriceList priceList = new PriceList();
23	    22	    private final PremiumPolicy premiumPolicy = new PremiumPolicy(priceList);
24	    23	    private final ClaimPolicy claimPolicy = new ClaimPolicy();
25	    24	
26	    25	    private final int yearsWithMHPCO;
27	    26	    private final Map<Integer, Policy> policiesByQuote = new HashMap<>();
28	    27	    private int contractsAlreadyHeld;
29	    28	
30	    29	    public ClaimOffice(int yearsWithMHPCO) {
31	    30	        this.yearsWithMHPCO = yearsWithMHPCO;
32	    31	    }
33	    32	
34	    33	    /**
35	    34	     * The office quotes a premium for the items brought and writes the policy
36	    35	     * insuring them, filed under the quote it answers. Every quote the office
37	    36	     * answers is another contract this customer holds, so the next one is a
38	    37	     * follow-up.
39	    38	     */
40	    39	    public int quote(int quoteReference, List<InsuredItem> insuredItems) {
41	    40	        Customer customer = new Customer(yearsWithMHPCO, contractsAlreadyHeld);
42	    41	        policiesByQuote.put(quoteReference, Policy.covering(insuredItems, priceList));
43	    42	        contractsAlreadyHeld++;
44	    43	        return premiumPolicy.quote(customer, insuredItems);
45	    44	    }
46	    45	
47	    46	    /**
48	    47	     * The office settles a reported incident against the policy a previous
49	    48	     * quote wrote, on that policy's own terms.
50	    49	     */
51	    50	    public Settlement settleClaim(int quoteReference, List<Damage> damages) {
52	    51	        Policy policy = policiesByQuote.get(quoteReference);
53	    52	        BigDecimal paid = policy.settle(damages, claimPolicy);
54	    53	        return new Settlement(paid, policy.remainingCap());
55	    54	    }
56	    55	
57	    56	    /** What one settled claim paid, and what the policy's cap has left afterwards. */
58	    57	    public record Settlement(BigDecimal payout, BigDecimal remainingCap) {
59	    58	    }
60	    59	}
