70	     9	import com.fasterxml.jackson.databind.JsonNode;
71	    10	import com.fasterxml.jackson.databind.ObjectMapper;
72	    11	import com.fasterxml.jackson.databind.node.ArrayNode;
73	    12	import com.fasterxml.jackson.databind.node.ObjectNode;
74	    13	
75	    14	/**
76	    15	 * Translates the JSON scenario protocol into MHPCO operations and back. The
77	    16	 * protocol field names are binding; what the office does with a step, and what
78	    17	 * it carries from one step to the next, is the {@link ClaimOffice}'s business.
79	    18	 */
80	    19	public class ClaimOfficeCli {
81	    20	
82	    21	    private static final ObjectMapper JSON = new ObjectMapper();
83	    22	
84	    23	    public void run(InputStream scenario, PrintStream results) {
85	    24	        try {
86	    25	            JsonNode input = JSON.readTree(scenario);
87	    26	            ClaimOffice office =
88	    27	                    new ClaimOffice(input.get("customer").get("yearsWithMHPCO").asInt());
89	    28	            ObjectNode output = JSON.createObjectNode();
90	    29	            ArrayNode resultsNode = output.putArray("results");
91	    30	            JsonNode steps = input.get("steps");
92	    31	            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
93	    32	                JsonNode step = steps.get(stepIndex);
94	    33	                if ("claim".equals(step.get("op").asText())) {
95	    34	                    writeSettlement(office.settleClaim(step.get("policy").asInt(), damages(step)),
96	    35	                            resultsNode.addObject());
97	    36	                    continue;
98	    37	                }
99	    38	                resultsNode.addObject().put("premium",
100	    39	                        office.quote(stepIndex, insuredItems(step)));
101	    40	            }
102	    41	            results.print(JSON.writeValueAsString(output));
103	    42	        } catch (IOException e) {
104	    43	            throw new UncheckedIOException(e);
105	    44	        }
106	    45	    }
107	    46	
108	    47	    private static void writeSettlement(ClaimOffice.Settlement settlement, ObjectNode result) {
109	    48	        result.put("payout", settlement.payout().intValueExact());
110	    49	        result.put("remainingCap", settlement.remainingCap().intValueExact());
111	    50	    }
112	    51	
113	    52	    private static List<Damage> damages(JsonNode claimStep) {
114	    53	        List<Damage> damages = new ArrayList<>();
115	    54	        for (JsonNode damage : claimStep.get("incident").get("damages")) {
116	    55	            damages.add(new Damage(damage.get("itemType").asText(),
117	    56	                    new BigDecimal(damage.get("amount").asText())));
118	    57	        }
119	    58	        return damages;
120	    59	    }
121	    60	
122	    61	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
123	    62	        List<InsuredItem> items = new ArrayList<>();
124	    63	        for (JsonNode item : quoteStep.get("items")) {
125	    64	            items.add(new InsuredItem(item.get("type").asText(),
126	    65	                    item.path("cursed").asBoolean(false),
127	    66	                    item.path("enchantment").asInt(0)));
128	    67	        }
129	    68	        return items;
130	    69	    }
131	    70	}
