133	     1	import java.math.BigDecimal;
134	     2	
135	     3	/**
136	     4	 * The MHPCO claim rules: what the office reimburses for a damage report against
137	     5	 * a policy, after the deductible and within the policy's payout cap.
138	     6	 *
139	     7	 * Two decisions the office revises on their own schedules meet here, in the
140	     8	 * order the specification fixes: its clause book states how much of a damage
141	     9	 * counts as reimbursable at all, and only then is the deductible borne. A new
142	    10	 * clause or a revised threshold is the clause book's business; repricing the
143	    11	 * deductible is this rule's.
144	    12	 *
145	    13	 * A payout is a payment out of the office, so its fraction of a G is rounded in
146	    14	 * the office's favor by {@link InOfficesFavor}.
147	    15	 */
148	    16	public class ClaimPolicy {
149	    17	
150	    18	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = new BigDecimal("100");
151	    19	    private static final BigDecimal UNRULY_ITEM_REIMBURSEMENT_RATE = new BigDecimal("0.5");
152	    20	
153	    21	    /**
154	    22	     * The office reimburses the reimbursable part of a damage less the
155	    23	     * deductible, never below nothing.
156	    24	     */
157	    25	    public BigDecimal reimbursementFor(BigDecimal damageAmount, InsuredItem damagedItem) {
158	    26	        return InOfficesFavor.payment(reimbursableDamageUnderClauses(damageAmount, damagedItem)
159	    27	                .subtract(DEDUCTIBLE_PER_DAMAGE)
160	    28	                .max(BigDecimal.ZERO));
161	    29	    }
162	    30	
163	    31	    /**
164	    32	     * How much of a damage the office's clause book lets it count as
165	    33	     * reimbursable, read from the damaged item and settled before the
166	    34	     * deductible. The high-enchantment clause reimburses an unruly item's damage
167	    35	     * at a reduced rate; a damage no clause speaks to counts in full.
168	    36	     *
169	    37	     * The office's second clause, that damage to an item of dragon material is
170	    38	     * fully reimbursed, is absent here deliberately rather than by oversight: in
171	    39	     * every case the specification states it grants exactly what a damage no
172	    40	     * clause speaks to already earns. Below the unruly threshold it reimburses in
173	    41	     * full, which is the default; at or above it the specification gives the
174	    42	     * reduced rate precedence. So the clause never changes a reimbursement, and
175	    43	     * the office does not record an item's material at all. A revision that gave
176	    44	     * dragon material its own rate, or precedence over the high-enchantment
177	    45	     * clause, would be the first to make the material worth recording.
178	    46	     */
179	    47	    private static BigDecimal reimbursableDamageUnderClauses(BigDecimal damageAmount,
180	    48	            InsuredItem damagedItem) {
181	    49	        if (damagedItem.isTooUnrulyToReimburseInFull()) {
182	    50	            return damageAmount.multiply(UNRULY_ITEM_REIMBURSEMENT_RATE);
183	    51	        }
184	    52	        return damageAmount;
185	    53	    }
186	    54	}
