188	     1	import java.util.List;
189	     2	
190	     3	/**
191	     4	 * What a policy covers: the items the office recorded when it wrote the policy,
192	     5	 * able to say which of them a reported damage is settled on.
193	     6	 *
194	     7	 * Reading a damage report against the covered items is a decision of its own,
195	     8	 * revised on its own schedule and quite apart from what one damage earns or what
196	     9	 * the cap allows. Two pending revisions are this coverage's alone: counting a
197	    10	 * policy's several items of one kind against the damages reported for that kind,
198	    11	 * and refusing a damage that names a kind the policy does not cover. Neither
199	    12	 * touches the claim rules or the cap.
200	    13	 */
201	    14	record Coverage(List<InsuredItem> insuredItems) {
202	    15	
203	    16	    static Coverage of(List<InsuredItem> insuredItems) {
204	    17	        return new Coverage(List.copyOf(insuredItems));
205	    18	    }
206	    19	
207	    20	    /**
208	    21	     * The covered item whose terms a reported damage is settled on: the office
209	    22	     * looks the reported kind of item up among the items it covers, and the
210	    23	     * claim rules read the clauses from it. A damage naming a kind of item the
211	    24	     * coverage does not include is no claim the office will settle.
212	    25	     *
213	    26	     * The office matches by the kind of item reported, which is all a single
214	    27	     * covered item of a kind needs. Counting several items of one kind against
215	    28	     * the damages reported for that kind is a separate decision the office has
216	    29	     * not been asked to make yet.
217	    30	     */
218	    31	    InsuredItem itemDamagedBy(Damage damage) {
219	    32	        for (InsuredItem insuredItem : insuredItems) {
220	    33	            if (insuredItem.type().equals(damage.itemType())) {
221	    34	                return insuredItem;
222	    35	            }
223	    36	        }
224	    37	        throw new IllegalArgumentException(
225	    38	                "the policy does not cover a " + damage.itemType());
226	    39	    }
227	    40	}
