229	     1	/**
230	     2	 * The customer a scenario is about, as the office knows them: their standing
231	     3	 * with the MHPCO at the moment a premium is quoted.
232	     4	 *
233	     5	 * Both facts here are the office's view of its relationship with this customer
234	     6	 * rather than of the items insured, so this is also where the office decides
235	     7	 * what that relationship entitles the customer to: whether they count as
236	     8	 * long-standing, and whether this contract is a follow-up. The rates those
237	     9	 * entitlements earn are the premium rules' business, in {@link PremiumPolicy}.
238	    10	 */
239	    11	public record Customer(int yearsWithMHPCO, int contractsAlreadyHeld) {
240	    12	
241	    13	    private static final int LOYALTY_YEARS = 2;
242	    14	
243	    15	    /**
244	    16	     * The office counts a customer as long-standing from 2 years of business
245	    17	     * with the MHPCO up; a newer customer earns no loyalty.
246	    18	     */
247	    19	    public boolean isLongStanding() {
248	    20	        return yearsWithMHPCO >= LOYALTY_YEARS;
249	    21	    }
250	    22	
251	    23	    /**
252	    24	     * Every contract after the customer's first is a follow-up, however long
253	    25	     * they have been with the office.
254	    26	     */
255	    27	    public boolean holdsFollowUpContract() {
256	    28	        return contractsAlreadyHeld > 0;
257	    29	    }
258	    30	}
