266	     1	import java.math.BigDecimal;
267	     2	import java.math.RoundingMode;
268	     3	
269	     4	/**
270	     5	 * The MHPCO rounds every amount to whole G in its own favor. One rule, read in
271	     6	 * the direction the money moves: a fraction of a G the customer owes the office
272	     7	 * is rounded up, a fraction the office owes the customer is rounded down. The
273	     8	 * office never loses the fraction.
274	     9	 *
275	    10	 * Intermediate amounts during a calculation stay exact fractions; only a final
276	    11	 * charge or payment is rounded.
277	    12	 */
278	    13	final class InOfficesFavor {
279	    14	
280	    15	    private static final int WHOLE_G = 0;
281	    16	
282	    17	    private InOfficesFavor() {
283	    18	    }
284	    19	
285	    20	    /** What the customer owes the office, rounded up: the fraction favors the office. */
286	    21	    static BigDecimal charge(BigDecimal amount) {
287	    22	        return amount.setScale(WHOLE_G, RoundingMode.CEILING);
288	    23	    }
289	    24	
290	    25	    /** What the office owes the customer, rounded down: the fraction favors the office. */
291	    26	    static BigDecimal payment(BigDecimal amount) {
292	    27	        return amount.setScale(WHOLE_G, RoundingMode.FLOOR);
293	    28	    }
294	    29	}
