305	    10	 * serves rather than sharing one vague "enchanted" predicate.
306	    11	 */
307	    12	public record InsuredItem(String type, boolean cursed, int enchantment) {
308	    13	
309	    14	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
310	    15	    private static final int UNRULY_ENCHANTMENT_LEVEL = 8;
311	    16	
312	    17	    /**
313	    18	     * The office counts an item as highly enchanted, and so as carrying a risk
314	    19	     * worth a surcharge, from enchantment level 5 up.
315	    20	     */
316	    21	    public boolean isHighlyEnchanted() {
317	    22	        return enchantment >= HIGH_ENCHANTMENT_LEVEL;
318	    23	    }
319	    24	
320	    25	    /**
