329	=============== PayoutCap.java
330	     1	import java.math.BigDecimal;
331	     2	
332	     3	/**
333	     4	 * The limit on everything a policy will ever pay out, and how much of it is
334	     5	 * left. The office caps a policy at twice the insurance sum of the items it
335	     6	 * covers.
336	     7	 *
337	     8	 * What the cap is worth and what it has left are one decision revised on its
338	     9	 * own schedule: a revision to the multiple, or one that let the cap replenish,
339	    10	 * is this cap's business and touches no claim rule. Premium modifiers are no
340	    11	 * part of it, which is why a cap is opened from an insurance sum and never from
341	    12	 * a premium.
342	    13	 */
343	    14	class PayoutCap {
344	    15	
345	    16	    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");
346	    17	
347	    18	    private BigDecimal remaining;
348	    19	
349	    20	    static PayoutCap forInsuranceSum(BigDecimal insuranceSum) {
350	    21	        return new PayoutCap(insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM));
351	    22	    }
352	    23	
353	    24	    private PayoutCap(BigDecimal remaining) {
354	    25	        this.remaining = remaining;
355	    26	    }
356	    27	
357	    28	    /** Pays what the cap still allows of a desired payout and consumes that much of it. */
358	    29	    BigDecimal pay(BigDecimal desiredPayout) {
359	    30	        BigDecimal paid = desiredPayout.min(remaining);
360	    31	        remaining = remaining.subtract(paid);
361	    32	        return paid;
362	    33	    }
363	    34	
364	    35	    BigDecimal remaining() {
365	    36	        return remaining;
366	    37	    }
367	    38	}
368	=============== Policy.java
369	     1	import java.math.BigDecimal;
370	     2	import java.util.List;
371	     3	
372	     4	/**
373	     5	 * A policy the office has written: the {@link Coverage} it was written over and
374	     6	 * the {@link PayoutCap} it was written under.
375	     7	 *
376	     8	 * Settling an incident against the policy is this policy's decision, not the
377	     9	 * protocol's, and all it decides is how the three parties to a settlement meet:
378	    10	 * the coverage says which covered item a reported damage is settled on, the
379	    11	 * {@link ClaimPolicy} says what that one damage earns, and the cap says how much
380	    12	 * of it is actually paid. So the deductible is borne once per damage reported
381	    13	 * and the cap is consumed in the order the damages are reported.
382	    14	 */
383	    15	public class Policy {
384	    16	
385	    17	    private final Coverage coverage;
386	    18	    private final PayoutCap payoutCap;
387	    19	
388	    20	    /**
389	    21	     * The office writes a policy over the items a customer brings: what it
390	    22	     * insures them for is the {@link PriceList}'s to state, and the cap that
391	    23	     * insurance sum earns is the cap's own rule. Premium modifiers are no part
392	    24	     * of it, which is why the policy is written from the covered items and never
393	    25	     * from the premium quoted for them.
394	    26	     */
395	    27	    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
396	    28	        return new Policy(Coverage.of(insuredItems),
397	    29	                PayoutCap.forInsuranceSum(priceList.insuranceSum(insuredItems)));
398	    30	    }
399	    31	
400	    32	    private Policy(Coverage coverage, PayoutCap payoutCap) {
401	    33	        this.coverage = coverage;
402	    34	        this.payoutCap = payoutCap;
403	    35	    }
404	    36	
405	    37	    /**
406	    38	     * What the office pays for one reported incident: every damage reimbursed on
407	    39	     * its own terms, the total limited to the cap the policy has left.
408	    40	     */
409	    41	    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
410	    42	        BigDecimal paid = BigDecimal.ZERO;
411	    43	        for (Damage damage : damages) {
412	    44	            paid = paid.add(payoutCap.pay(claimPolicy.reimbursementFor(
413	    45	                    damage.amount(), coverage.itemDamagedBy(damage))));
414	    46	        }
415	    47	        return paid;
416	    48	    }
417	    49	
418	    50	    public BigDecimal remainingCap() {
419	    51	        return payoutCap.remaining();
420	    52	    }
421	    53	}
422	=============== PremiumPolicy.java
423	     1	import java.math.BigDecimal;
424	     2	import java.util.List;
425	     3	
426	     4	/**
427	     5	 * The MHPCO premium rules: the two scopes of premium modifier, the processing
428	     6	 * fee, applied to the base premium the {@link PriceList} states for the insured
429	     7	 * items.
430	     8	 *
431	     9	 * A premium is a charge to the customer, so its fraction of a G is rounded in
432	    10	 * the office's favor by {@link InOfficesFavor}.
433	    11	 */
434	    12	public class PremiumPolicy {
435	    13	
436	    14	    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
437	    15	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
438	    16	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
439	    17	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = new BigDecimal("0.20");
440	    18	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = new BigDecimal("0.15");
441	    19	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
442	    20	
443	    21	    private final PriceList priceList;
444	    22	
445	    23	    /** The premium rules read their base premiums from the office's price list. */
446	    24	    public PremiumPolicy(PriceList priceList) {
447	    25	        this.priceList = priceList;
448	    26	    }
449	    27	
450	    28	    /**
451	    29	     * The office charges both kinds of modifier on a base premium, never on each
452	    30	     * other: an item modifier on the affected item's own base premium, a
453	    31	     * policy-wide modifier on the policy base premium. So the two are summed
454	    32	     * alongside the base premium rather than compounded in sequence, and the
455	    33	     * processing fee is added at the very end.
456	    34	     */
457	    35	    public int quote(Customer customer, List<InsuredItem> insuredItems) {
458	    36	        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
459	    37	        BigDecimal premium = policyBasePremium
460	    38	                .add(itemRiskSurcharges(insuredItems))
461	    39	                .add(policyWideModifiers(policyBasePremium, customer))
462	    40	                .add(PROCESSING_FEE);
463	    41	        return InOfficesFavor.charge(premium).intValueExact();
464	    42	    }
465	    43	
466	    44	    /**
467	    45	     * Item-scope modifiers: each is charged on the base premium of the affected
468	    46	     * item alone, so a modifier on one item never touches another item's share
469	    47	     * of the policy. What one item's risks cost is {@link #riskSurcharge}'s
470	    48	     * business; this rule only states that the policy owes the sum of them.
471	    49	     */
472	    50	    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
473	    51	        BigDecimal surcharges = BigDecimal.ZERO;
474	    52	        for (InsuredItem insuredItem : insuredItems) {
475	    53	            surcharges = surcharges.add(riskSurcharge(insuredItem));
476	    54	        }
477	    55	        return surcharges;
478	    56	    }
479	    57	
480	    58	    /**
481	    59	     * What the risks the office reads in one item cost, charged on that item's
482	    60	     * own base premium. A curse and a high enchantment are separate risks, so an
483	    61	     * item carrying both is surcharged for both rather than letting the graver
484	    62	     * risk absorb the other.
485	    63	     */
486	    64	    private BigDecimal riskSurcharge(InsuredItem insuredItem) {
487	    65	        BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
488	    66	        BigDecimal surcharge = BigDecimal.ZERO;
489	    67	        if (insuredItem.cursed()) {
490	    68	            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
491	    69	        }
