573	    32	    }
574	    33	
575	    34	    /** Every component is charged and insured alike, whatever its type. */
576	    35	    private static final Tariff COMPONENT_TARIFF =
577	    36	            new Tariff(new BigDecimal("25"), new BigDecimal("250"));
578	    37	
579	    38	    /** The published price list: the item types the office insures, and at what. */
580	    39	    private static final Map<String, Tariff> TARIFF = Map.of(
581	    40	            "sword", new Tariff(new BigDecimal("100"), new BigDecimal("1000")),
582	    41	            "amulet", new Tariff(new BigDecimal("60"), new BigDecimal("600")),
583	    42	            "staff", new Tariff(new BigDecimal("80"), new BigDecimal("800")),
584	    43	            "potion", new Tariff(new BigDecimal("40"), new BigDecimal("400")),
585	    44	            "rune", COMPONENT_TARIFF,
586	    45	            "moonstone", COMPONENT_TARIFF);
