613	    72	        BigDecimal total = BigDecimal.ZERO;
614	    73	        for (Map.Entry<String, Integer> alikeItems : groupedByAlikeness(insuredItems).entrySet()) {
615	    74	            total = total.add(basePremium(alikeItems.getKey(), alikeItems.getValue()));
616	    75	        }
617	    76	        return total;
618	    77	    }
