630	    89	        Map<String, Integer> counts = new LinkedHashMap<>();
631	    90	        for (InsuredItem insuredItem : insuredItems) {
632	    91	            counts.merge(alikenessGroupOf(insuredItem.type()), 1, Integer::sum);
633	    92	        }
634	    93	        return counts;
635	    94	    }
