641	   100	     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
642	   101	     * returning a family name here instead of the type itself.
643	   102	     */
644	   103	    private static String alikenessGroupOf(String itemType) {
645	   104	        return itemType;
646	   105	    }
