648	   107	    /**
649	   108	     * What a holding of alike items of one type costs: the type's own rate per
650	   109	     * item, except that a block of components is offered at the block rate.
651	   110	     */
652	   111	    private static BigDecimal basePremium(String itemType, int count) {
653	   112	        if (qualifiesForBlockRate(itemType, count)) {
654	   113	            return COMPONENT_BLOCK_BASE_PREMIUM;
655	   114	        }
656	   115	        return TARIFF.get(itemType).basePremium().multiply(BigDecimal.valueOf(count));
657	   116	    }
658	   117	
659	   118	    /**
660	   119	     * The office grants the block rate only to a holding of exactly 3 alike
661	   120	     * components. It neither prices a part of a block at the block rate (4
662	   121	     * components are not a block) nor breaks a larger holding down into blocks
663	   122	     * (7 components are priced as 7, not as two blocks and one loose component).
664	   123	     * Main items are never blocked: 3 swords are 3 swords.
665	   124	     */
666	   125	    private static boolean qualifiesForBlockRate(String itemType, int alikeItemCount) {
667	   126	        return COMPONENT_TYPES.contains(itemType) && alikeItemCount == COMPONENT_BLOCK_SIZE;
668	   127	    }
