public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
    BigDecimal paid = BigDecimal.ZERO;
    for (Damage damage : damages) {
        paid = paid.add(settleOne(damage, claimPolicy));
    }
    return paid;
}

private BigDecimal settleOne(Damage damage, ClaimPolicy claimPolicy) {
    return payoutCap.pay(claimPolicy.reimbursementFor(
            damage.amount(), coverage.itemDamagedBy(damage)));
}

